func NewFlag(f *flipt.Flag) *Flag {
	af := &Flag{
		Key:          f.Key,
		Name:         f.Name,
		Description:  f.Description,
		Enabled:      f.Enabled,
		NamespaceKey: f.NamespaceKey,
	}
	if f.DefaultVariant != nil {
		af.DefaultVariant = f.DefaultVariant.Key
	}
	return af
}

